// Rodada 63: oferta do negócio de um membro no grupo, uma por semana por pessoa, só com a página ativa.
const OFFER_WEEK_MS=7*864e5;
const bizOpen=b=>!!b?.live&&!b.suspended&&!b.paused;
const canOffer=g=>!!g?.allowOffers&&bizOpen(state.myBiz);
function nextOfferAt(g){const t=(g.offerAt||{})[state.profile.name];return t&&t+OFFER_WEEK_MS>Date.now()?t+OFFER_WEEK_MS:0;}
function openPostEditor(gid,type){
 const g=gById(gid);if(!g||!g.on||!canPost())return;
 if(!postDraft||postDraft.gid!==gid)postDraft={gid,type:'post',text:'',alsoCity:false,date:dateISO(7),time:'09:00',place:'',opts:['','','','']};
 if(type)postDraft.type=type;const d=postDraft,types=[['post','Publicação','edit'],['question','Pergunta','help'],['event','Evento','event'],['poll','Enquete','ballot']];
 if(canOffer(g))types.push(['offer','Oferta do meu negócio','sell']);else if(d.type==='offer')d.type='post';
 let c=`<md-chip-set class="post-types">${types.map(([v,t,ic])=>`<md-filter-chip label="${t}" ${d.type===v?'selected':''} data-action="post-type" data-value="${v}">${icon(ic,'icon')}</md-filter-chip>`).join('')}</md-chip-set>`;
 c+=field('post-text',{post:'O que você quer compartilhar?',question:'O que você quer perguntar?',event:'Nome do evento',poll:'Pergunta da enquete',offer:'Descreva a oferta'}[d.type],d.text,d.type==='event'?'maxlength="120"':'type="textarea" rows="4" maxlength="2000"');
 if(d.type==='question')c+=`<label class="choice"><md-checkbox id="post-city" ${d.alsoCity?'checked':''} aria-label="Também perguntar à cidade"></md-checkbox><span class="txt"><b>Também perguntar à cidade</b><small>A pergunta também vai para Indicações, onde qualquer membro de ${esc(g.city)} pode responder.</small></span></label>`;
 if(d.type==='event')c+=`<div class="form-grid"><label class="field-label">Data<input id="post-date" type="date" min="${dateISO()}" value="${d.date}"></label><label class="field-label">Horário<input id="post-time" type="time" value="${d.time}"></label></div>${field('post-place','Local (público)',d.place,'maxlength="120"')}`;
 if(d.type==='poll')c+=d.opts.map((o,i)=>field('poll-'+i,`Opção ${i+1}${i>1?' (opcional)':''}`,o,'maxlength="60"')).join('');
 if(d.type==='offer')c+=`<div class="who-sees">${icon('storefront')}<span><b>Link:</b> a oferta leva à página de ${esc(state.myBiz.name)}. Uma por semana neste grupo, sempre com o rótulo Oferta.</span></div>`;
 c+=`<div class="who-sees">${icon(g.privacy==='fechado'?'lock':'visibility')}<span><b>Quem vê:</b> ${g.privacy==='fechado'?'só os membros aprovados do grupo.':'membros do grupo. O grupo é aberto, então quem entrar também verá.'}${d.type==='question'&&d.alsoCity?` A pergunta também aparece para ${esc(g.city)} em Indicações.`:''}</span></div>`;
 showDialog(`Publicar em ${g.t}`,c,`${btn('Cancelar','close-dialog','','text')}${btn('Publicar','submit-post',gid,'filled','send')}`);
 $('#post-city')?.addEventListener('change',e=>{readPostDraft();postDraft.alsoCity=e.target.checked;openPostEditor(gid);});
}
function readPostDraft(){if(!postDraft)return;const v=id=>$('#'+id,dialog)?.value;postDraft.text=v('post-text')??postDraft.text;if(postDraft.type==='event'){postDraft.date=v('post-date')||postDraft.date;postDraft.time=v('post-time')||postDraft.time;postDraft.place=v('post-place')??postDraft.place;}if(postDraft.type==='poll')postDraft.opts=postDraft.opts.map((o,i)=>v('poll-'+i)??o);const cb=$('#post-city',dialog);if(cb)postDraft.alsoCity=cb.checked;}
function openGroupCreator(tpl){
 if(!canPost())return;if(!groupDraft)groupDraft={name:'',about:'',tpl:'livre',privacy:'aberto',rules:GTPL.livre.rules};
 if(tpl&&tpl!==groupDraft.tpl){const keep=groupDraft.rules&&groupDraft.rules!==GTPL[groupDraft.tpl].rules;groupDraft.tpl=tpl;if(!keep)groupDraft.rules=GTPL[tpl].rules;}
 const d=groupDraft;
 const c=`${field('group-name','Nome do grupo',d.name,'required minlength="3" maxlength="60" supporting-text="Ex.: Moradores do Residencial X, Pais da Escola Y"')}${field('group-about','Sobre o grupo',d.about,'type="textarea" rows="2" maxlength="300"')}<p class="field-cap">Modelo</p><md-chip-set class="post-types">${Object.entries(GTPL).filter(([k])=>k!=='turma').map(([k,t])=>`<md-filter-chip label="${t.name}" ${d.tpl===k?'selected':''} data-action="group-tpl" data-value="${k}">${icon(t.ic,'icon')}</md-filter-chip>`).join('')}</md-chip-set><p class="field-cap">Privacidade</p>${[['aberto','Aberto','Qualquer membro de '+state.city+' entra com um toque e vê as publicações.','public'],['fechado','Fechado','Quem quiser entrar pede, e você aprova. Só membros veem as publicações.','lock']].map(([v,t,s,ic])=>`<label class="choice"><md-radio name="gprivacy" value="${v}" ${d.privacy===v?'checked':''} aria-label="${t}"></md-radio><span class="txt"><b>${icon(ic)} ${t}</b><small>${s}</small></span></label>`).join('')}${field('group-rules','Regras do grupo',d.rules,'type="textarea" rows="3" maxlength="600"')}<p class="form-note">Quem cria administra o grupo e pode nomear moderadores. Todos os membros do Bivaque são verificados.</p>`;
 showDialog('Criar grupo',c,`${btn('Cancelar','close-dialog','','text')}${btn('Criar grupo','submit-group','','filled','group_add')}`);
}
function readGroupDraft(){if(!groupDraft)return;const v=id=>$('#'+id,dialog)?.value;groupDraft.name=v('group-name')??groupDraft.name;groupDraft.about=v('group-about')??groupDraft.about;groupDraft.rules=v('group-rules')??groupDraft.rules;groupDraft.privacy=$$('md-radio[name=gprivacy]',dialog).find(r=>r.checked)?.value||groupDraft.privacy;}
function openManage(gid){
 const g=gById(gid);if(!g||g.role!=='admin')return;
 const c=`${g.privacy==='fechado'?`<p class="field-cap">Pedidos de entrada</p><div class="stack">${g.requests.map((r,i)=>`<div class="choice"><span class="avatar">${esc(initals(r.name))}</span><span class="txt"><b>${esc(r.name)}</b><small>${esc(r.note||'Membro verificado')}</small></span>${btn('Aprovar','approve-req',`${g.id}|${i}`,'tonal')}${iconBtn('close','deny-req',`${g.id}|${i}`,'Recusar pedido')}</div>`).join('')||'<p class="small muted">Nenhum pedido agora.</p>'}</div>`:''}<p class="field-cap">Moderadores</p><div class="g-pills">${g.mods.map(m=>pill(m,'','shield_person')).join('')||'<span class="small muted">Nenhum moderador.</span>'}</div><div class="row">${selectField('mod-add','Nomear moderador',[['','Escolher membro'],...['Paulo R.','Diego F.','Marcos T.','Luana M.'].filter(n=>!g.mods.includes(n)).map(n=>[n,n])],'')}${btn('Nomear','add-mod',g.id,'text')}</div>${selectField('manage-privacy','Privacidade',[['aberto','Aberto'],['fechado','Fechado']],g.privacy)}${field('manage-pinned','Aviso fixado',g.pinned,'type="textarea" rows="2" maxlength="300"')}${field('manage-rules','Regras',g.rules,'type="textarea" rows="3" maxlength="600"')}<div class="choice"><span class="txt"><b>Permitir Oferta de negócio de membro</b><small>Uma por semana, sempre com o rótulo Oferta. Patrocinado nunca aparece no grupo.</small></span><md-switch id="manage-offers" ${g.allowOffers?'selected':''} aria-label="Permitir ofertas"></md-switch></div>`;
 showDialog(`Gerenciar ${g.t}`,c,`${btn('Fechar','close-dialog','','text')}${btn('Salvar','save-manage',g.id,'filled')}`);
}
function interestsHtml(sel){return `<md-chip-set class="interest-chips">${INTERESTS.map(([k,t,ic])=>`<md-filter-chip label="${t}" ${sel.includes(k)?'selected':''} data-action="interest-toggle" data-value="${k}">${icon(ic,'icon')}</md-filter-chip>`).join('')}</md-chip-set><p class="form-note">${sel.length}/3 escolhidos. Você pode mudar depois em Comunidade › Grupos.</p>`;}
function openInterests(){if(!interestsDraft)interestsDraft=[...(state.profile.interests||[])];showDialog('Do que você quer participar?',`<p class="form-note">Marque até 3. Usamos isso só para sugerir grupos.</p>${interestsHtml(interestsDraft)}`,`${btn('Cancelar','close-dialog','','text')}${btn('Salvar','save-interests','','filled')}`);}
